    }
    fprintf(fp,
            "step,time,"
            "y_rhs_prev_time_level_enabled,"
            "mean_xBtot_old,"
            "mean_xBtot_before_step,mean_xBtot_after_phi_update,mean_xBtot_after_Y_update,mean_xBtot_after_Y_to_xB,"
