static int run_y_update_mass_projection(const PFParams *P,
                                        int step,
                                        int post_conversion_step,
                                        const char *target_mode,
                                        double target_sum_xBtot,
                                        double Y_upper_cap,
                                        double *d_phi_r,
                                        double *d_eta_r,
                                        double *d_Y_base_r,
                                        double *d_Y_r,
                                        double *d_xB_r,
                                        int total_r,
                                        FILE *projection_fp,
                                        double *lambda_shift_out,
                                        double *sum_before_out,
                                        double *sum_after_out,
                                        double *min_xB_before_out,
                                        double *max_xB_before_out,
                                        double *min_xB_after_out,
                                        double *max_xB_after_out,
                                        int *converged_out) {
    if (!P || !d_phi_r || !d_eta_r || !d_Y_base_r || !d_Y_r || !d_xB_r) return 0;
    const double tol_abs = P->y_update_mass_projection_tol * fmax(1.0, fabs(target_sum_xBtot));
    double sum_before = gpu_reduce_sum_model_xBtot(P, d_phi_r, d_eta_r, d_xB_r, total_r);
    double min_xB_before = 0.0, max_xB_before = 0.0;
    gpu_reduce_min_max(d_xB_r, total_r, &min_xB_before, &max_xB_before);
    CUDA_CHECK(cudaMemcpy(d_Y_base_r, d_Y_r, (size_t)total_r * sizeof(double), cudaMemcpyDeviceToDevice));

    double lambda_best = 0.0;
    int converged = (fabs(sum_before - target_sum_xBtot) <= tol_abs) ? 1 : 0;
    int num_iter = 0;
    const char *notes = converged ? "already_within_tolerance" : "";

    auto eval_lambda = [&](double lambda) -> double {
        launch_apply_Y_shift_recompute_xB_kernel(d_Y_base_r, d_Y_r, d_xB_r,
                                                 lambda, P->Y_clip, Y_upper_cap,
                                                 P->xB_eps, total_r);
        return gpu_reduce_sum_model_xBtot(P, d_phi_r, d_eta_r, d_xB_r, total_r);
    };

    if (!converged) {
        double lo = -50.0, hi = 50.0;
        double flo = eval_lambda(lo) - target_sum_xBtot;
        double fhi = eval_lambda(hi) - target_sum_xBtot;
        lambda_best = 0.0;
        if (fabs(flo) <= tol_abs) {
            lambda_best = lo;
            converged = 1;
        } else if (fabs(fhi) <= tol_abs) {
            lambda_best = hi;
            converged = 1;
        } else {
            if (flo * fhi > 0.0) {
                lo = -100.0;
                hi = 100.0;
                flo = eval_lambda(lo) - target_sum_xBtot;
                fhi = eval_lambda(hi) - target_sum_xBtot;
            }
            if (flo * fhi <= 0.0) {
                for (num_iter = 1; num_iter <= P->y_update_mass_projection_max_iter; ++num_iter) {
                    double mid = 0.5 * (lo + hi);
                    double sum_mid = eval_lambda(mid);
                    double fmid = sum_mid - target_sum_xBtot;
                    lambda_best = mid;
                    if (fabs(fmid) <= tol_abs) {
                        converged = 1;
                        break;
                    }
                    if (flo * fmid <= 0.0) {
                        hi = mid;
                        fhi = fmid;
                    } else {
                        lo = mid;
                        flo = fmid;
                    }
                }
                if (!converged) {
                    notes = "max_iter_reached";
                }
            } else {
                notes = "projection_bracket_failed";
                launch_apply_Y_shift_recompute_xB_kernel(d_Y_base_r, d_Y_r, d_xB_r,
                                                         0.0, P->Y_clip, Y_upper_cap,
                                                         P->xB_eps, total_r);
                lambda_best = 0.0;
            }
        }
    }

    if (!converged && strcmp(notes, "projection_bracket_failed") != 0) {
        launch_apply_Y_shift_recompute_xB_kernel(d_Y_base_r, d_Y_r, d_xB_r,
                                                 lambda_best, P->Y_clip, Y_upper_cap,
                                                 P->xB_eps, total_r);
    }

    double sum_after = gpu_reduce_sum_model_xBtot(P, d_phi_r, d_eta_r, d_xB_r, total_r);
    double min_xB_after = 0.0, max_xB_after = 0.0;
    gpu_reduce_min_max(d_xB_r, total_r, &min_xB_after, &max_xB_after);
    if (projection_fp) {
        write_y_update_mass_projection_row(
            projection_fp, step, post_conversion_step, target_mode,
            target_sum_xBtot, sum_before, sum_after,
            sum_before - target_sum_xBtot,
            sum_after - target_sum_xBtot,
            lambda_best, num_iter, converged,
            sum_after - target_sum_xBtot,
            min_xB_before, max_xB_before,
            min_xB_after, max_xB_after,
            0.0, 0.0, notes);
        fflush(projection_fp);
    }
    if (lambda_shift_out) *lambda_shift_out = lambda_best;
    if (sum_before_out) *sum_before_out = sum_before;
    if (sum_after_out) *sum_after_out = sum_after;
    if (min_xB_before_out) *min_xB_before_out = min_xB_before;
    if (max_xB_before_out) *max_xB_before_out = max_xB_before;
    if (min_xB_after_out) *min_xB_after_out = min_xB_after;
    if (max_xB_after_out) *max_xB_after_out = max_xB_after;
    if (converged_out) *converged_out = converged;
    return 1;
}

struct PfZeroModeSolveResult {
    double lambda = 0.0;
    double residual_code = 0.0;
    double derivative_code = 0.0;
    double Y_star_min = 0.0;
    double Y_star_max = 0.0;
    double lambda_lower = 0.0;
    double lambda_upper = 0.0;
    int iterations = 0;
    int newton_steps = 0;
    int bisection_steps = 0;
    int converged = 0;
};

static std::uint64_t pf_zero_mode_parameter_fingerprint(const PFParams *P) {
    if (!P) return 0U;
    std::uint64_t hash = 1469598103934665603ULL;
    auto add = [&](const void *data, size_t size) {
        hash = pf_zero_mode::fnv1a64(data, size, hash);
    };
    add(&P->Nx, sizeof(P->Nx));
    add(&P->Ny, sizeof(P->Ny));
    add(&P->Nz, sizeof(P->Nz));
    add(&P->dt, sizeof(P->dt));
    add(&P->temperature_C, sizeof(P->temperature_C));
    add(&P->dx, sizeof(P->dx));
    add(&P->dy, sizeof(P->dy));
    add(&P->dz, sizeof(P->dz));
    add(&P->v_A, sizeof(P->v_A));
    add(&P->v_B, sizeof(P->v_B));
    add(&P->D_alpha, sizeof(P->D_alpha));
    add(&P->D_compound, sizeof(P->D_compound));
    add(&P->L_phi, sizeof(P->L_phi));
    add(&P->kappa_phi, sizeof(P->kappa_phi));
    add(&P->W, sizeof(P->W));
    add(&P->Y_clip, sizeof(P->Y_clip));
    add(&P->xB_eps, sizeof(P->xB_eps));
    add(&P->enable_Y_rhs_previous_time_level,
        sizeof(P->enable_Y_rhs_previous_time_level));
    add(&P->disable_Y_rhs_gamma_term,
        sizeof(P->disable_Y_rhs_gamma_term));
    add(P->pf_composition_mode, strlen(P->pf_composition_mode) + 1U);
    add(P->pf_y_update_mode, strlen(P->pf_y_update_mode) + 1U);
    add(pf_zero_mode::kExplicitContextNV1,
        strlen(pf_zero_mode::kExplicitContextNV1) + 1U);
    add(pf_zero_mode::kReactionTangentNV1,
        strlen(pf_zero_mode::kReactionTangentNV1) + 1U);
    return hash == 0U ? 1U : hash;
}

static std::uint64_t elastic_solver_parameter_fingerprint(
    const PFParams *P) {
    if (!P) return 0U;
    std::uint64_t hash = 1469598103934665603ULL;
    auto add = [&](const void *data, size_t size) {
        hash = pf_zero_mode::fnv1a64(data, size, hash);
    };
    add(&P->Nx, sizeof(P->Nx));
    add(&P->Ny, sizeof(P->Ny));
    add(&P->Nz, sizeof(P->Nz));
    add(&P->dx, sizeof(P->dx));
    add(&P->dy, sizeof(P->dy));
    add(&P->dz, sizeof(P->dz));
    add(&P->elastic_enabled, sizeof(P->elastic_enabled));
    add(&P->elastic_warm_start_enabled,
        sizeof(P->elastic_warm_start_enabled));
    add(&P->elastic_residual_control_enabled,
        sizeof(P->elastic_residual_control_enabled));
    add(&P->elastic_iter_min, sizeof(P->elastic_iter_min));
    add(&P->elastic_iter_max, sizeof(P->elastic_iter_max));
    add(&P->elastic_residual_tolerance,
        sizeof(P->elastic_residual_tolerance));
    add(&P->elastic_residual_absolute_floor,
        sizeof(P->elastic_residual_absolute_floor));
    add(&P->elastic_fail_on_nonconvergence,
        sizeof(P->elastic_fail_on_nonconvergence));
    const double stiffness[] = {
        P->S_11, P->S_12, P->S_13, P->S_14, P->S_15, P->S_16,
        P->S_22, P->S_23, P->S_24, P->S_25, P->S_26,
        P->S_33, P->S_34, P->S_35, P->S_36,
        P->S_44, P->S_45, P->S_46, P->S_55, P->S_56, P->S_66,
        P->S_p_11, P->S_p_12, P->S_p_13, P->S_p_14, P->S_p_15,
        P->S_p_16, P->S_p_22, P->S_p_23, P->S_p_24, P->S_p_25,
        P->S_p_26, P->S_p_33, P->S_p_34, P->S_p_35, P->S_p_36,
        P->S_p_44, P->S_p_45, P->S_p_46, P->S_p_55, P->S_p_56,
        P->S_p_66};
    add(stiffness, sizeof(stiffness));
    const double strain[] = {
        P->eps_xx00, P->eps_yy00, P->eps_zz00,
        P->eps_yz00, P->eps_xz00, P->eps_xy00,
        P->eps_iso_over_vB, P->E0_xx, P->E0_yy, P->E0_zz,
        P->E0_yz, P->E0_xz, P->E0_xy};
    add(strain, sizeof(strain));
    return hash == 0U ? 1U : hash;
}

static int run_pf_conserved_y_zero_mode_host(
    const PFParams *P,
    const double *d_Y_star_r,
    const double *d_phi_r,
    double *d_mass_terms_r,
    double *d_derivative_terms_r,
    double *d_pair_reduction_work,
    int pair_reduction_work_capacity,
    double target_mass_code,
    double Y_upper_cap,
    double tolerance_relative,
    int max_iterations,
    int total_r,
    int *d_invalid,
    double *d_Y_r,
    double *d_xB_r,
    PfZeroModeSolveResult *result)
{
    if (!P || !d_Y_star_r || !d_phi_r || !d_mass_terms_r ||
        !d_derivative_terms_r || !d_pair_reduction_work ||
        pair_reduction_work_capacity <= 0 ||
        !d_invalid || !d_Y_r || !d_xB_r ||
        !result || total_r <= 0 || !(tolerance_relative > 0.0) ||
        max_iterations <= 0 || !std::isfinite(target_mass_code) ||
        !std::isfinite(Y_upper_cap)) {
        return 0;
    }
    PfZeroModeSolveResult status;
    gpu_reduce_min_max(d_Y_star_r, total_r,
                       &status.Y_star_min, &status.Y_star_max);
    if (!std::isfinite(status.Y_star_min) ||
        !std::isfinite(status.Y_star_max)) {
        *result = status;
        return 0;
    }
    status.lambda_lower = -P->Y_clip - status.Y_star_min;
    status.lambda_upper = Y_upper_cap - status.Y_star_max;
    const double interval_roundoff =
        128.0 * DBL_EPSILON *
        fmax(fmax(fabs(status.lambda_lower),
                  fabs(status.lambda_upper)), 1.0);
    if (!std::isfinite(status.lambda_lower) ||
        !std::isfinite(status.lambda_upper) ||
        status.lambda_lower > status.lambda_upper + interval_roundoff) {
        *result = status;
        return 0;
    }

    const double tolerance =
        tolerance_relative * fmax(fabs(target_mass_code), 1.0);
    auto evaluate = [&](double lambda, double *mass,
                        double *derivative) -> int {
        launch_compute_pf_Y_zero_mode_terms_kernel(
            d_Y_star_r, d_phi_r, lambda, P->v_B,
            d_mass_terms_r, d_derivative_terms_r, total_r);
        CUDA_CHECK(cudaGetLastError());
        if (!gpu_reduce_sum_pair_reuse(
                d_mass_terms_r, d_derivative_terms_r, total_r,
                d_pair_reduction_work, pair_reduction_work_capacity,
                mass, derivative)) {
            return 0;
        }
        return std::isfinite(*mass) && std::isfinite(*derivative);
    };

    double lower_mass = 0.0, lower_derivative = 0.0;
    double upper_mass = 0.0, upper_derivative = 0.0;
    if (!evaluate(status.lambda_lower, &lower_mass, &lower_derivative) ||
        !evaluate(status.lambda_upper, &upper_mass, &upper_derivative)) {
        *result = status;
        return 0;
    }
    double F_lower = lower_mass - target_mass_code;
    double F_upper = upper_mass - target_mass_code;
    if (F_lower > tolerance || F_upper < -tolerance) {
        *result = status;
        return 0;
    }

    status.lambda = fmin(fmax(0.0, status.lambda_lower),
                         status.lambda_upper);
    double mass = 0.0;
    if (!evaluate(status.lambda, &mass, &status.derivative_code)) {
        *result = status;
        return 0;
    }
    status.residual_code = mass - target_mass_code;
    for (int iteration = 0;
         iteration < max_iterations &&
         fabs(status.residual_code) > tolerance;
         ++iteration) {
        if (status.residual_code < 0.0) {
            status.lambda_lower = status.lambda;
            F_lower = status.residual_code;
        } else {
            status.lambda_upper = status.lambda;
            F_upper = status.residual_code;
        }
        double candidate = NAN;
        if (status.derivative_code > 0.0 &&
            std::isfinite(status.derivative_code)) {
            candidate =
                status.lambda -
                status.residual_code / status.derivative_code;
        }
        if (std::isfinite(candidate) &&
            candidate > status.lambda_lower &&
            candidate < status.lambda_upper) {
            ++status.newton_steps;
        } else {
            candidate =
                0.5 * (status.lambda_lower + status.lambda_upper);
            ++status.bisection_steps;
        }
        status.lambda = candidate;
        if (!evaluate(status.lambda, &mass, &status.derivative_code)) {
            *result = status;
            return 0;
        }
        status.residual_code = mass - target_mass_code;
        status.iterations = iteration + 1;
    }
    status.converged =
        fabs(status.residual_code) <= tolerance ? 1 : 0;
    if (!status.converged ||
        !launch_validate_pf_Y_zero_mode_bounds_kernel(
            d_Y_star_r, status.lambda, -P->Y_clip, Y_upper_cap,
            total_r, d_invalid)) {
        *result = status;
        return 0;
    }
    launch_apply_pf_Y_zero_mode_shift_kernel(
        d_Y_star_r, status.lambda, d_Y_r, d_xB_r, total_r);
    CUDA_CHECK(cudaGetLastError());
    *result = status;
    return 1;
}

