            D->D_alpha_ref_phys, D->c_tot_phys, D->v_A, D->v_B, D->zeta_eta, D->zeta0_eta,
            D->Mcrit_eta, D->gp_M_eta_phys_input, D->gp_M_eta_ratio_to_crit_input, D->M_eta_used, D->M_eta_over_Mcrit,
