static int load_pfparams_override_file(PFParams *P, const char *path) {
    if (!P || !path || path[0] == '\0') return 0;
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "[fatal] Could not open pf-param file: %s\n", path);
        return 0;
    }

    char line[2048];
    int line_no = 0;
    int applied = 0;
    PFParamOverridePresence presence;
    memset(&presence, 0, sizeof(presence));
    while (fgets(line, sizeof(line), fp) != NULL) {
        line_no++;
        char *comment = strchr(line, '#');
        if (comment) *comment = '\0';
        trim_inplace(line);
        if (line[0] == '\0') continue;

        char *sep = strchr(line, '=');
        if (!sep) {
            fprintf(stderr, "[fatal] %s:%d expected key=value format\n", path, line_no);
            fclose(fp);
            return 0;
        }
        *sep = '\0';
        char key[512];
        char value[1536];
        strncpy(key, line, sizeof(key) - 1);
        key[sizeof(key) - 1] = '\0';
        strncpy(value, sep + 1, sizeof(value) - 1);
        value[sizeof(value) - 1] = '\0';
        trim_inplace(key);
        trim_inplace(value);

        int rc = apply_pfparams_override_key(P, key, value, path, line_no);
        if (rc < 0) {
            fclose(fp);
            return 0;
        }
        if (rc == 0) {
            fprintf(stderr, "[warn] %s:%d unknown key ignored: %s\n", path, line_no, key);
            continue;
        }
        mark_pfparams_presence(&presence, key);
        applied++;
    }
    fclose(fp);
    if (!validate_required_pfparams_presence(&presence, path)) {
        return 0;
    }
    printf("[pf-param-file] loaded %d override(s) from %s\n", applied, path);
    return 1;
}

static int q_transport_conservative_local_redistribution(
    const PFParams *P,
    const double *d_q_before,
    const double *d_divJ,
    const double *d_phi,
    double *d_q_after,
    int total_r,
    double dt,
    int max_radius,
    double tol,
    int *violating_cells_out,
    int *max_radius_used_out,
    double *unresolved_mass_out)
{
    if (!P || !d_q_before || !d_divJ || !d_phi || !d_q_after) return 0;
    std::vector<double> q0((size_t)total_r);
    std::vector<double> divJ((size_t)total_r);
    std::vector<double> phi((size_t)total_r);
    std::vector<double> q((size_t)total_r);
    std::vector<double> alpha((size_t)total_r);
    std::vector<double> residual((size_t)total_r, 0.0);
    CUDA_CHECK(cudaMemcpy(q0.data(), d_q_before, (size_t)total_r * sizeof(double),
                          cudaMemcpyDeviceToHost));
    CUDA_CHECK(cudaMemcpy(divJ.data(), d_divJ, (size_t)total_r * sizeof(double),
                          cudaMemcpyDeviceToHost));
    CUDA_CHECK(cudaMemcpy(phi.data(), d_phi, (size_t)total_r * sizeof(double),
                          cudaMemcpyDeviceToHost));

    int violating = 0;
    for (int idx = 0; idx < total_r; ++idx) {
        alpha[(size_t)idx] = 1.0 - h_of_phi(fmin(fmax(phi[(size_t)idx], 0.0), 1.0));
        const double trial = q0[(size_t)idx] + dt * divJ[(size_t)idx];
        const double bounded = fmin(fmax(trial, 0.0), alpha[(size_t)idx]);
        q[(size_t)idx] = bounded;
        residual[(size_t)idx] = trial - bounded;
        if (!isfinite(trial) || fabs(residual[(size_t)idx]) > tol) violating++;
    }

    const int Nx = P->Nx, Ny = P->Ny, Nz = P->Nz;
    auto index3 = [Ny, Nz](int i, int j, int k) {
        return (i * Ny + j) * Nz + k;
    };
    int max_used = 0;
    double unresolved = 0.0;
    for (int idx = 0; idx < total_r; ++idx) {
        double amount = residual[(size_t)idx];
        if (!isfinite(amount)) {
            unresolved += INFINITY;
            continue;
        }
        if (fabs(amount) <= tol) continue;
        const int k0 = idx % Nz;
        const int tmp = idx / Nz;
        const int j0 = tmp % Ny;
        const int i0 = tmp / Ny;
        for (int radius = 1; radius <= max_radius && fabs(amount) > tol; ++radius) {
            for (int di = -radius; di <= radius && fabs(amount) > tol; ++di) {
                for (int dj = -radius; dj <= radius && fabs(amount) > tol; ++dj) {
                    for (int dk = -radius; dk <= radius && fabs(amount) > tol; ++dk) {
                        if (std::max(std::max(abs(di), abs(dj)), abs(dk)) != radius) continue;
                        const int ii = (i0 + di + Nx) % Nx;
                        const int jj = (j0 + dj + Ny) % Ny;
                        const int kk = (k0 + dk + Nz) % Nz;
                        const int nidx = index3(ii, jj, kk);
                        if (amount > 0.0) {
                            const double capacity = alpha[(size_t)nidx] - q[(size_t)nidx];
                            if (capacity <= 0.0) continue;
                            const double moved = fmin(amount, capacity);
                            q[(size_t)nidx] += moved;
                            amount -= moved;
                        } else {
                            const double available = q[(size_t)nidx];
                            if (available <= 0.0) continue;
                            const double moved = fmin(-amount, available);
                            q[(size_t)nidx] -= moved;
                            amount += moved;
                        }
                    }
                }
            }
            if (fabs(amount) <= tol) max_used = std::max(max_used, radius);
        }
        unresolved += fabs(amount);
    }
    if (violating_cells_out) *violating_cells_out = violating;
    if (max_radius_used_out) *max_radius_used_out = max_used;
    if (unresolved_mass_out) *unresolved_mass_out = unresolved;
    if (!isfinite(unresolved) || unresolved > tol * fmax(1.0, (double)violating)) {
        return 0;
    }
    CUDA_CHECK(cudaMemcpy(d_q_after, q.data(), (size_t)total_r * sizeof(double),
                          cudaMemcpyHostToDevice));
    return 1;
}

int main(int argc, char **argv) {
    // 立即刷新输出，确保能看到调试信息
    setbuf(stdout, NULL);
    setbuf(stderr, NULL);

    const double wall_t0 = wall_time_sec_monotonic();

    // 解析命令行参数
    PFParams P;
    params_default(&P);

    int wants_help = 0;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            wants_help = 1;
            break;
        }
    }

    const char *pf_param_file = NULL;
    char continue_phi_vtk_pre_scan[4096] = {0};
    char effective_pf_param_file[4096] = {0};
    char continue_case_pf_param_file[4096] = {0};
    char pf_zero_mode_selector[64] = {0};
    char pf_zero_mode_backend[64] = {0};
    char pf_checkpoint_path[4096] = {0};
    char pf_restart_from[4096] = {0};
    char pf_initial_state_class[96] = {0};
    char pf_fixture_manifest_sha256[96] = {0};
    char pf_profile_library_manifest_sha256[96] = {0};
    char mechanics_only_replay_dir[4096] = {0};
    char mechanics_sync_diagnostic_dir[4096] = {0};
    int mechanics_replay_force_zero_initial = 0;
    int mechanics_sync_diagnostic_step = 0;
    double pf_zero_mode_tolerance_relative = 1.0e-12;
    int pf_zero_mode_max_iterations = 24;
    int pf_checkpoint_every = 0;
    snprintf(pf_zero_mode_selector, sizeof(pf_zero_mode_selector),
             "%s", pf_zero_mode::kModeOff);
    snprintf(pf_zero_mode_backend, sizeof(pf_zero_mode_backend),
             "%s", pf_zero_mode::kHostBackendV1);
    snprintf(pf_initial_state_class, sizeof(pf_initial_state_class),
             "%s", pf_zero_mode::kLegacyInitialStateClass);
    snprintf(pf_fixture_manifest_sha256,
             sizeof(pf_fixture_manifest_sha256), "%s",
             pf_zero_mode::kLegacyInitialStateClass);
    snprintf(pf_profile_library_manifest_sha256,
             sizeof(pf_profile_library_manifest_sha256), "%s",
             pf_zero_mode::kLegacyInitialStateClass);

    // Optional: interpret radius in physical nm and convert to internal length units later,
    // after we can infer (dx_phys_m_run, unit_to_m_run) from PF inputs.
    int has_radius_phys_nm = 0;
    double radius_phys_nm = 0.0;
    int has_xB_matrix_override = 0;
    double xB_matrix_override = 0.0;

    for (int i = 1; i < argc; ++i) {
        const char *v = get_flag_value(argc, argv, &i, "--pf-param-file");
        if (v != NULL) {
            pf_param_file = v;
        }
        v = get_flag_value(argc, argv, &i, "--continue-phi-vtk");
        if (v != NULL) {
            snprintf(continue_phi_vtk_pre_scan, sizeof(continue_phi_vtk_pre_scan), "%s", v);
        }
    }
    if (!wants_help && pf_param_file == NULL) {
        fprintf(stderr,
                "[fatal] 物理参数不再使用 main_cuda 内置默认值。请通过 --pf-param-file <path> 提供完整物理输入。\n");
        fprintf(stderr,
                "        可先运行: python3 Unit_Psedobinary.py --input-json physical_inputs.example.json --output-pf-param-file /tmp/generated_pf.params\n");
        return 2;
    }
    if (argc >= 2 && argv[1][0] != '-') { P.Nx = atoi(argv[1]); }
    if (argc >= 3 && argv[2][0] != '-') { P.Ny = atoi(argv[2]); }
    if (argc >= 4 && argv[3][0] != '-') { P.Nz = atoi(argv[3]); }
    if (argc >= 5 && argv[4][0] != '-') { P.dt = atof(argv[4]); }
    if (argc >= 6 && argv[5][0] != '-') { P.nsteps = atoi(argv[5]); }
    if (argc >= 7 && argv[6][0] != '-') { P.out_every = atoi(argv[6]); }
    if (argc >= 8 && argv[7][0] != '-') { P.csv_out_every = atoi(argv[7]); }  // CSV输出间隔参数
    if (argc >= 9 && argv[8][0] != '-') { P.elastic_enabled = atoi(argv[8]); }  // 弹性功能开关（0/1）
    if (pf_param_file != NULL) {
        snprintf(effective_pf_param_file, sizeof(effective_pf_param_file), "%s", pf_param_file);
        if (!load_pfparams_override_file(&P, effective_pf_param_file)) {
            return 2;
        }
        // 物理输入文件中的 dt 作为默认时间步；若后续显式给出 --minimize-dt，仍允许覆盖。
        P.minimize_dt = P.dt;
    }
    if (continue_phi_vtk_pre_scan[0] != '\0' &&
        build_continue_case_pf_param_path(continue_phi_vtk_pre_scan,
                                          continue_case_pf_param_file,
                                          sizeof(continue_case_pf_param_file))) {
        struct stat st;
        if (stat(continue_case_pf_param_file, &st) == 0) {
            if (pf_param_file == NULL) {
                if (!load_pfparams_override_file(&P, continue_case_pf_param_file)) {
                    return 2;
                }
                snprintf(effective_pf_param_file, sizeof(effective_pf_param_file), "%s", continue_case_pf_param_file);
                P.minimize_dt = P.dt;
                printf("[continue-param] loaded stored PF params from %s\n", continue_case_pf_param_file);
            } else {
                printf("[continue-param] explicit --pf-param-file takes precedence; ignoring stored PF params at %s\n",
                       continue_case_pf_param_file);
            }
        } else {
            printf("[continue-param] no stored PF params next to continue VTK, fallback to %s\n",
                   effective_pf_param_file);
        }
    }
    if (P.pf_params_schema_version != PF_PARAMS_SCHEMA_VERSION) {
        fprintf(stderr,
                "[fatal] pf_params_schema_version mismatch: file=%d expected=%d. 请重新跑 Unit_Psedobinary.py\n",
                P.pf_params_schema_version, PF_PARAMS_SCHEMA_VERSION);
        return 2;
    }
    // 诊断开关（VTK / 弹性 bulk 惩罚）不再通过命令行控制，统一在 params_default 中设置

    // ----------------------------
    // 预扫描 init-test-id 和 init-case-tag（在详细 flag 解析前）
    // ----------------------------
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--init-test-id") == 0 && i + 1 < argc) {
            P.init_test_id = atoi(argv[i + 1]);
        }
        if (strcmp(argv[i], "--init-case-tag") == 0 && i + 1 < argc) {
            strncpy(P.init_case_tag, argv[i + 1], sizeof(P.init_case_tag) - 1);
            P.init_case_tag[sizeof(P.init_case_tag) - 1] = '\0';
        }
    }
    // 先根据 test preset 设置一组初始化参数，后续显式 flags 可以在此基础上覆盖
    apply_init_test_preset(&P);

    // ----------------------------
    // Parse optional flags (do not break positional args)
    // ----------------------------
    for (int i = 1; i < argc; ++i) {
        if (!starts_with(argv[i], "--")) continue;
        if (strcmp(argv[i], "--help") == 0 || strcmp(argv[i], "-h") == 0) {
            printf("Usage (positional, legacy):\n");
            printf("  ./main_cuda Nx Ny Nz dt nsteps out_every csv_out_every elastic_enabled(0/1)\n");
            printf("    注: dt 位置参数仅作 legacy 回退；若 --pf-param-file 中提供 dt，则以参数文件为准。\n");
            printf("\nFlags (optional):\n");
            printf("  --mode=dynamics|dynamics-continue|minimize|minimize-continue\n");
            printf("  --pf-param-file <path>  required: load complete physical PF inputs (key=value)\n");
            printf("  --minimize-max-iter <n>\n");
            printf("  --minimize-dt <dt>\n");
            printf("  --minimize-mass-constraint       preserve exact C_B_tot during full-model minimize\n");
            printf("  --minimize-freeze-phi            validation-only: hold raw phi byte-identical and equilibrate conserved Y/xB\n");
            printf("  --minimize-target-mass-code <v>  total code ledger; <=0 freezes exact initial ledger\n");
            printf("  --minimize-mass-tolerance-relative <v> (default: 1e-12)\n");
            printf("  --minimize-mass-max-iterations <n> (default: 64)\n");
            printf("  --eta-lambda-vol <value>   lambda_vol under-relaxation 阻尼系数 (default: 0.2, range: [0,1])\n");
            printf("  --minimize-rms-dY-threshold <val>    Y 收敛判据 (default: 5e-5)\n");
            printf("  --minimize-rms-res-threshold <val>   Euler-Lagrange/KKT 残差判据 (default: 1e-4)\n");
            printf("  --minimize-vol-err-rel-threshold <val>  体积约束相对误差判据 (default: 1e-4, V0<=0 时以第一步体积为参考)\n");
            printf("  --minimize-post-projection-iters <n>  后投影修正子步数 (default: 1, n>=0)\n");
            printf("  --temperature-C <val>   物理温度（摄氏度），默认 380.0\n");
            printf("  --V0 <val>              target <h(phi)>; if <=0 use initial mean_h\n");
            printf("  --radius <val>          seed radius in internal length units (same units as P.dx)\n");
            printf("  --radius-phys-nm <nm>   seed radius in physical nm (converted using dx_phys inferred from lambda_sm_m/(2*ic_phi_iface_w))\n");
            printf("  --minimize-resample-elastic-every N   true residual diagnostic interval; N<=0 disables\n");
            printf("  --elastic 0|1           override elastic (0=off, 1=on)\n");
            printf("  elastic_warm_start_enabled=1 and elastic_residual_control_enabled=1\n");
            printf("                             default accelerated elastic fixed-point solver for dynamics/minimize\n");
            printf("  elastic_iter_min=N       minimum fixed-point updates before residual stopping\n");
            printf("  elastic_iter_max=N       hard fixed-point update cap\n");
            printf("  elastic_residual_tolerance=v  relative k-space displacement residual\n");
            printf("  elastic_residual_absolute_floor=v denominator floor for near-zero states\n");
            printf("  elastic_fail_on_nonconvergence=1  fail closed at the hard cap\n");
            printf("\nInitialization (symmetry-breaking tests):\n");
            printf("  --init-shape sphere|ellipsoid\n");
            printf("  --init-axis-ratio-rx <val>\n");
            printf("  --init-axis-ratio-ry <val>\n");
            printf("  --init-axis-ratio-rz <val>\n");
            printf("  --init-tilt-theta-deg <val>\n");
            printf("  --init-tilt-phi-deg <val>\n");
            printf("  --init-center-shift-x <val>\n");
            printf("  --init-center-shift-y <val>\n");
            printf("  --init-center-shift-z <val>\n");
            printf("  --init-phi-noise-amp <val>\n");
            printf("  --init-phi-noise-seed <int>\n");
            printf("  --seed <int>            global deterministic RNG seed for event sampling and init randomness\n");
            printf("  --gp-to-beta-conversion-mass-audit-enabled 0|1\n");
            printf("  --gp-to-beta-stop-after-conversion-audit 0|1\n");
            printf("  --post-conversion-y-update-audit-enabled 0|1\n");
            printf("  --post-conversion-y-update-audit-steps <n>\n");
            printf("  --y-update-mass-projection-enabled 0|1\n");
            printf("  --y-update-mass-projection-report-enabled 0|1\n");
            printf("  --y-update-mass-projection-max-iter <n>\n");
            printf("  --y-update-mass-projection-tol <val>\n");
            printf("  --y-update-mass-projection-target-mode pre_Y_update|post_conversion_baseline\n");
            printf("\nPure-PF conserved Y zero mode and restart (GP/source paths must be OFF):\n");
            printf("  --pf-zero-mode OFF|PF_CONSERVED_Y_ZERO_MODE_V1\n");
            printf("  --pf-zero-mode-backend HOST_NEWTON_BISECTION_V1\n");
            printf("  --pf-zero-mode-tol-rel <value>       default 1e-12\n");
            printf("  --pf-zero-mode-max-iter <n>          default 24\n");
            printf("  --pf-checkpoint-every <n>            0 disables periodic checkpoints\n");
            printf("  --pf-checkpoint-path <path>          atomic full-state checkpoint\n");
            printf("  --pf-restart-from <path>             provenance-strict restart\n");
            printf("  --pf-initial-state-class <name>      checkpoint-pinned initial-state policy\n");
            printf("  --pf-fixture-manifest-sha256 <hex>   checkpoint-pinned fixture identity\n");
            printf("  --pf-profile-library-manifest-sha256 <hex> checkpoint-pinned profile-library identity\n");
            printf("  --mechanics-only-replay-dir <path>  solve accepted checkpoint phi/xB without advancing PF\n");
            printf("  --mechanics-replay-initialization checkpoint_warm|zero\n");
            printf("  --mechanics-sync-diagnostic-dir <path>  write synchronized online mechanical fields\n");
            printf("  --mechanics-sync-diagnostic-step <n>    solver step whose accepted source field is written\n");
            printf("  --init-test-id <int>    preset index for batch tests (0..7, <0 to disable)\n");
            printf("  --continue-phi-vtk <path>  continuation: load phi from ASCII VTK and continue minimize\n");
            printf("  --continue-xB-vtk <path>   continuation(full-model): optional xB ASCII VTK; if missing, rebuild xB/Y from phi via init logic\n");
            printf("                               若 VTK 同目录存在 pf_input.params，则 continue 会优先使用该参数快照\n");
            printf("  --init-mode raw_fields      initialize from Python-generated raw phi/xB[/dY_dt_prev][/eta] fields\n");
            printf("  --init-phi-raw <path>       raw_fields phi_init.raw (C order, idx=i*(Ny*Nz)+j*Nz+k)\n");
            printf("  --init-xB-raw <path>        raw_fields xB_init.raw\n");
            printf("  --init-dY-dt-prev-raw <path> optional provenance-pinned raw_fields time-level history; omitted means exact fresh zero history\n");
            printf("  --init-eta-raw <path>       raw_fields optional eta_init.raw (default zero)\n");
            printf("  --init-meta <path>          raw_fields init_meta.json with grid/dx/lambda/dtype metadata\n");
            printf("\nScheduled nucleation TEST mode (explicit opt-in, dynamics only):\n");
            printf("  --enable-scheduled-nucleation-test\n");
            printf("  --scheduled-nuc-source-dyn-dir <dir>       no-strain dynamic-continue source dir\n");
            printf("  --scheduled-nuc-profile-dir <dir>          faceted profile dir containing faceted_family_profiles.csv\n");
            printf("  --scheduled-nuc-source-step latest|N       diagnostic source step label (default latest)\n");
            printf("  --scheduled-nuc-steps 100,300,600\n");
            printf("  --scheduled-nuc-centers-nm \"100,100,100;180,100,100;100,180,100\"\n");
            printf("  --scheduled-nuc-seed-metadata <json>       library-seed metadata JSON; can auto-derive scheduled step/profile/source\n");
            printf("  --scheduled-nuc-t-nuc-code <time>          nucleation time in code units for delayed insertion derivation\n");
            printf("  --scheduled-nuc-t-nuc-s <time>             nucleation time in physical seconds for delayed insertion derivation\n");
            printf("  --scheduled-nuc-xB-edge-mode sample-current-background-shell\n");
            printf("  --scheduled-nuc-local-comp-outer-nm 20.0\n");
            printf("  --scheduled-nuc-local-comp-taper-nm 5.0\n");
            printf("  --scheduled-nucleation-write-event-vtk 0|1\n");
            printf("\nDynamics mass-drift diagnostics (explicit opt-in):\n");
            printf("  --enable-dynamics-mass-diagnostics\n");
            printf("  --dynamics-mass-diag-interval <n>   write diagnostics every n steps (default 1)\n");
            printf("  --enable-Y-rhs-previous-time-level  use phi^n/Y^n for explicit Y-RHS terms (default off)\n");
            printf("  --disable-Y-rhs-gamma-term          diagnostic mode only; set term_gamma = 0 (default off)\n");
            printf("  --Y-rhs-term-h-scale <s>            diagnostic scaling for term_h (default 1.0)\n");
            printf("  --enable-Y-rhs-picard               diagnostic mode only; Picard iterate gamma*dYdt coupling (default off)\n");
            printf("  --Y-rhs-picard-iters <n>            Picard iterations for Y RHS gamma*dYdt (default 1)\n");
            printf("  --Y-rhs-picard-omega <w>            Picard under-relaxation omega in (0,1] (default 1.0)\n");
            printf("\nMinimize 最小可运行示例（小网格，无弹性）：\n");
            printf("  ./main_cuda 32 32 32 0.05 100 10 10 0 --mode=minimize --minimize-max-iter 200 --minimize-dt 0.05\n");
            printf("Minimize 带弹性、指定 V0：\n");
            printf("  ./main_cuda 64 64 64 0.05 500 50 10 1 --mode=minimize --minimize-max-iter 500 --minimize-dt 0.05 --V0 0.1 --elastic 1\n");
            printf("\nMinimize full-model（带化学+扩散+体积约束）的示例：\n");
            printf("  ./main_cuda 64 64 64 0.05 500 50 10 1 --mode=minimize --minimize-full-model --minimize-max-iter 500 --minimize-dt 0.05 --V0 0.1 --elastic 1\n");
            return 0;
        }
        const char *v = NULL;
        if ((v = get_flag_value(argc, argv, &i, "--pf-zero-mode")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--pf_zero_mode")) != NULL) {
            snprintf(pf_zero_mode_selector, sizeof(pf_zero_mode_selector), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--pf-zero-mode-backend")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--pf_zero_mode_backend")) != NULL) {
            snprintf(pf_zero_mode_backend, sizeof(pf_zero_mode_backend), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--pf-zero-mode-tol-rel")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--pf_zero_mode_tol_rel")) != NULL) {
            pf_zero_mode_tolerance_relative = atof(v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--pf-zero-mode-max-iter")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--pf_zero_mode_max_iter")) != NULL) {
            pf_zero_mode_max_iterations = atoi(v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--pf-checkpoint-every")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--pf_checkpoint_every")) != NULL) {
            pf_checkpoint_every = atoi(v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--pf-checkpoint-path")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--pf_checkpoint_path")) != NULL) {
            snprintf(pf_checkpoint_path, sizeof(pf_checkpoint_path), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--pf-restart-from")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--pf_restart_from")) != NULL) {
            snprintf(pf_restart_from, sizeof(pf_restart_from), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i,
                                "--pf-initial-state-class")) != NULL ||
            (v = get_flag_value(argc, argv, &i,
                                "--pf_initial_state_class")) != NULL) {
            snprintf(pf_initial_state_class,
                     sizeof(pf_initial_state_class), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i,
                                "--pf-fixture-manifest-sha256")) != NULL ||
            (v = get_flag_value(argc, argv, &i,
                                "--pf_fixture_manifest_sha256")) != NULL) {
            snprintf(pf_fixture_manifest_sha256,
                     sizeof(pf_fixture_manifest_sha256), "%s", v);
            continue;
        }
        if ((v = get_flag_value(
                 argc, argv, &i,
                 "--pf-profile-library-manifest-sha256")) != NULL ||
            (v = get_flag_value(
                 argc, argv, &i,
                 "--pf_profile_library_manifest_sha256")) != NULL) {
            snprintf(pf_profile_library_manifest_sha256,
                     sizeof(pf_profile_library_manifest_sha256), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i,
                                "--mechanics-only-replay-dir")) != NULL) {
            snprintf(mechanics_only_replay_dir,
                     sizeof(mechanics_only_replay_dir), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i,
                                "--mechanics-replay-initialization")) != NULL) {
            if (strcmp(v, "zero") == 0) {
                mechanics_replay_force_zero_initial = 1;
            } else if (strcmp(v, "checkpoint_warm") == 0) {
                mechanics_replay_force_zero_initial = 0;
            } else {
                fprintf(stderr,
                        "[fatal] unsupported mechanics replay initialization: %s\n",
                        v);
                return 2;
            }
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i,
                                "--mechanics-sync-diagnostic-dir")) != NULL) {
            snprintf(mechanics_sync_diagnostic_dir,
                     sizeof(mechanics_sync_diagnostic_dir), "%s", v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i,
                                "--mechanics-sync-diagnostic-step")) != NULL) {
            mechanics_sync_diagnostic_step = atoi(v);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--mode")) != NULL) {
            if (strcmp(v, "minimize") == 0) P.mode = 1;
            else if (strcmp(v, "minimize-continue") == 0) {
                P.mode = 1;
                P.minimize_continue_from_vtk = 1;
            }
            else if (strcmp(v, "dynamics-continue") == 0) {
                P.mode = 0;
            }
            else P.mode = 0;
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--init-mode")) != NULL) {
            if (strcmp(v, "raw_fields") == 0) {
                P.init_mode_raw_fields = 1;
            } else {
                fprintf(stderr, "[fatal] unsupported --init-mode '%s'. Supported: raw_fields\n", v);
                return 2;
            }
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--init-phi-raw")) != NULL) {
            strncpy(P.init_phi_raw_path, v, sizeof(P.init_phi_raw_path) - 1);
            P.init_phi_raw_path[sizeof(P.init_phi_raw_path) - 1] = '\0';
            P.init_mode_raw_fields = 1;
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--init-xB-raw")) != NULL) {
            strncpy(P.init_xB_raw_path, v, sizeof(P.init_xB_raw_path) - 1);
            P.init_xB_raw_path[sizeof(P.init_xB_raw_path) - 1] = '\0';
            P.init_mode_raw_fields = 1;
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--init-dY-dt-prev-raw")) != NULL) {
            strncpy(P.init_dY_dt_prev_raw_path, v, sizeof(P.init_dY_dt_prev_raw_path) - 1);
            P.init_dY_dt_prev_raw_path[sizeof(P.init_dY_dt_prev_raw_path) - 1] = '\0';
            P.init_mode_raw_fields = 1;
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--init-eta-raw")) != NULL) {
            strncpy(P.init_eta_raw_path, v, sizeof(P.init_eta_raw_path) - 1);
            P.init_eta_raw_path[sizeof(P.init_eta_raw_path) - 1] = '\0';
            P.init_mode_raw_fields = 1;
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--init-meta")) != NULL) {
            strncpy(P.init_meta_path, v, sizeof(P.init_meta_path) - 1);
            P.init_meta_path[sizeof(P.init_meta_path) - 1] = '\0';
            P.init_mode_raw_fields = 1;
            continue;
        }
        if (strcmp(argv[i], "--enable-scheduled-nucleation-test") == 0) {
            P.scheduled_nuc_enabled = 1;
            continue;
        }
        if (strcmp(argv[i], "--use-manual-nucleus") == 0) {
            if (i + 1 < argc && argv[i + 1][0] != '-') {
                P.scheduled_nuc_use_manual_nucleus = parse_bool_text_cpp(argv[++i], 1);
            } else {
                P.scheduled_nuc_use_manual_nucleus = 1;
            }
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--use_manual_nucleus")) != NULL ||
            (v = get_flag_value(argc, argv, &i, "--use-manual-nucleus-mode")) != NULL) {
            P.scheduled_nuc_use_manual_nucleus = parse_bool_text_cpp(v, 0);
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--nucleus-selector-script")) != NULL) {
            strncpy(P.scheduled_nuc_selector_script, v, sizeof(P.scheduled_nuc_selector_script) - 1);
            P.scheduled_nuc_selector_script[sizeof(P.scheduled_nuc_selector_script) - 1] = '\0';
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--nucleus-catalog-json")) != NULL) {
            strncpy(P.scheduled_nuc_catalog_json, v, sizeof(P.scheduled_nuc_catalog_json) - 1);
            P.scheduled_nuc_catalog_json[sizeof(P.scheduled_nuc_catalog_json) - 1] = '\0';
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--selected-nucleus-json")) != NULL) {
            strncpy(P.scheduled_nuc_selected_json, v, sizeof(P.scheduled_nuc_selected_json) - 1);
            P.scheduled_nuc_selected_json[sizeof(P.scheduled_nuc_selected_json) - 1] = '\0';
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--selected-nucleus-log")) != NULL) {
            strncpy(P.scheduled_nuc_selection_log, v, sizeof(P.scheduled_nuc_selection_log) - 1);
            P.scheduled_nuc_selection_log[sizeof(P.scheduled_nuc_selection_log) - 1] = '\0';
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--scheduled-nuc-source-dyn-dir")) != NULL) {
            strncpy(P.scheduled_nuc_source_dyn_dir, v, sizeof(P.scheduled_nuc_source_dyn_dir) - 1);
            P.scheduled_nuc_source_dyn_dir[sizeof(P.scheduled_nuc_source_dyn_dir) - 1] = '\0';
            continue;
        }
        if ((v = get_flag_value(argc, argv, &i, "--scheduled-nuc-profile-dir")) != NULL) {
            strncpy(P.scheduled_nuc_profile_dir, v, sizeof(P.scheduled_nuc_profile_dir) - 1);
